		)
	}
	return nil
}

func isValidRepoFilter(repo string) bool {
	if repo == AllReposFilter {
		return true
	}
	if strings.Contains(repo, " ") {
		return false
	}
	parts := strings.Split(repo, "/")
	return len(parts) == 2 && parts[0] != "" && parts[1] != ""
}

